static uint16_t load_be16_unaligned(const uint8_t *p) {
    return (uint16_t)(((uint16_t)p[0] << 8) | (uint16_t)p[1]);
}

static uint32_t load_be32_unaligned(const uint8_t *p) {
    return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) |
           ((uint32_t)p[2] << 8) | (uint32_t)p[3];
}

static bool ipv4_header_checksum_valid(const uint8_t *header) {
    uint32_t sum = 0;
    for (size_t i = 0; i < 20; i += 2) {
        sum += load_be16_unaligned(header + i);
    }
    while (sum >> 16) {
        sum = (sum & 0xffffu) + (sum >> 16);
    }
    return (sum & 0xffffu) == 0xffffu;
}

/*
 * Strict wire-format acceptance.  Endpoint validity and the case-specific
 * 4D DATA payload length are deliberately handled by the collector after
 * this routine has accepted the frame as wire-valid.
 */
bool epic_parse_roce(const uint8_t *frame, size_t frame_len,
                     epic_roce_packet_t *out) {
    if (!frame || !out) {
        return false;
    }
    memset(out, 0, sizeof(*out));

    /* Ethernet + minimal IPv4 + UDP + BTH + ICRC. */
    if (frame_len < sizeof(epic_eth_t) + sizeof(epic_ipv4_t) +
                        sizeof(epic_udp_t) + sizeof(epic_bth_t) + 4) {
        return false;
    }

    if (load_be16_unaligned(frame + 12) != ETHERTYPE_IPV4) {
        return false;
    }

    const uint8_t *ip = frame + sizeof(epic_eth_t);
    if (ip[0] != 0x45 || ip[9] != IPPROTO_UDP) {
        return false;
    }
    uint16_t flags_frag = load_be16_unaligned(ip + 6);
    if (flags_frag != 0x0000u && flags_frag != 0x4000u) {
        return false;
    }
    if (!ipv4_header_checksum_valid(ip)) {
        return false;
    }

    uint16_t ip_total = load_be16_unaligned(ip + 2);
    if ((uint64_t)sizeof(epic_eth_t) + ip_total != frame_len ||
        ip_total < sizeof(epic_ipv4_t) + sizeof(epic_udp_t) +
                        sizeof(epic_bth_t) + 4) {
        return false;
    }

    const uint8_t *udp = ip + sizeof(epic_ipv4_t);
    uint16_t udp_len = load_be16_unaligned(udp + 4);
    if ((uint32_t)udp_len != (uint32_t)ip_total - sizeof(epic_ipv4_t) ||
        udp_len < sizeof(epic_udp_t) + sizeof(epic_bth_t) + 4) {
        return false;
    }
    if (load_be16_unaligned(udp) != EPIC_ROCE_UDP_PORT ||
        load_be16_unaligned(udp + 2) != EPIC_ROCE_UDP_PORT) {
        return false;
    }
    if (load_be16_unaligned(udp + 6) != 0) {
        return false;
    }

    const uint8_t *bth = udp + sizeof(epic_udp_t);
    uint8_t opcode = bth[0];
    if (bth[1] != 0 || load_be16_unaligned(bth + 2) != 0xffffu) {
        return false;
    }
    uint32_t qpn = load_be32_unaligned(bth + 4);
    uint32_t apsn = load_be32_unaligned(bth + 8);
    if ((qpn & 0xff000000u) != 0) {
        return false;
    }

    out->opcode = opcode;
    out->dst_qpn = qpn & 0x00ffffffu;
    out->psn = apsn & 0x00ffffffu;
    memcpy(&out->src_ip, ip + 12, sizeof(out->src_ip));
    memcpy(&out->dst_ip, ip + 16, sizeof(out->dst_ip));
    out->src_port = load_be16_unaligned(udp);
    out->dst_port = load_be16_unaligned(udp + 2);

    if (opcode == ROCE_OPCODE_ACK) {
        if ((apsn >> 24) != 0 ||
            udp_len != sizeof(epic_udp_t) + sizeof(epic_bth_t) +
                           sizeof(epic_aeth_t) + 4) {
            return false;
        }
        const uint8_t *aeth = bth + sizeof(epic_bth_t);
        uint32_t aeth_value = load_be32_unaligned(aeth);
        if ((aeth_value >> 24) != 0x1fu ||
            (aeth_value & 0x00ffffffu) != ((out->psn + 1u) & 0x00ffffffu)) {
            return false;
        }
        out->is_ack = true;
        out->msn = aeth_value & 0x00ffffffu;
    } else if (opcode == ROCE_OPCODE_SEND_ONLY) {
        if ((apsn >> 24) != 0x80u) {
            return false;
        }
        out->is_data = true;
        out->payload = bth + sizeof(epic_bth_t);
        out->payload_len = (size_t)udp_len - sizeof(epic_udp_t) -
                           sizeof(epic_bth_t) - 4u;
    } else {
        return false;
    }

    uint32_t stored_icrc;
    memcpy(&stored_icrc, frame + frame_len - 4, sizeof(stored_icrc));
    if (stored_icrc != epic_compute_icrc(frame, frame_len)) {
        return false;
    }

    out->valid = true;
    return true;
}
